func newExpense() unsafe.Pointer { return unsafe.Pointer(new(payexpense.Expense)) }

func newNExpense(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]payexpense.Expense, n)))
}

func ptrExpense(p unsafe.Pointer, c int32) any {
	r := (*payexpense.Expense)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (**string)(unsafe.Pointer(&r.ShipmentID))
	case 5:
		return (**string)(unsafe.Pointer(&r.PayCodeID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.AmountMinor
	case 8:
		return &r.CurrencyCode
	case 9:
		return &r.Description
	case 10:
		return &r.IncurredDate
	case 11:
		return (**string)(unsafe.Pointer(&r.ReceiptDocumentID))
	case 12:
		return (*string)(unsafe.Pointer(&r.SubmittedByUserID))
	case 13:
		return &r.ReviewNote
	case 14:
		return (**string)(unsafe.Pointer(&r.ReviewedByID))
	case 15:
		return &r.ReviewedAt
	case 16:
		return (**string)(unsafe.Pointer(&r.SettlementLineID))
	case 17:
		return &r.Version
	case 18:
		return &r.CreatedAt
	case 19:
		return &r.UpdatedAt
	}
	return nil
}

func valueExpense(p unsafe.Pointer, c int32) any {
	r := (*payexpense.Expense)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		if r.ShipmentID == nil {
			return nil
		}
		return string(*r.ShipmentID)
	case 5:
		if r.PayCodeID == nil {
			return nil
		}
		return string(*r.PayCodeID)
	case 6:
		return string(r.Status)
	case 7:
		return r.AmountMinor
	case 8:
		return r.CurrencyCode
	case 9:
		return r.Description
	case 10:
		return r.IncurredDate
	case 11:
		if r.ReceiptDocumentID == nil {
			return nil
		}
		return string(*r.ReceiptDocumentID)
	case 12:
		return string(r.SubmittedByUserID)
	case 13:
		if r.ReviewNote == "" {
			return nil
		}
		return r.ReviewNote
	case 14:
		if r.ReviewedByID == nil {
			return nil
		}
		return string(*r.ReviewedByID)
	case 15:
		if r.ReviewedAt == nil {
			return nil
		}
		return *r.ReviewedAt
	case 16:
		if r.SettlementLineID == nil {
			return nil
		}
		return string(*r.SettlementLineID)
	case 17:
		return r.Version
	case 18:
		return r.CreatedAt
	case 19:
		return r.UpdatedAt
	}
	return nil
}

func attachExpense(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*payexpense.Expense)(p)
	switch rel {
	case 0:
		r.Worker = (*worker.Worker)(child)
	case 1:
		r.PayCode = (*paycode.PayCode)(child)
	case 2:
		r.ReviewedBy = (*tenant.User)(child)
	}
}

func beforeCreateExpense(ctx context.Context, p unsafe.Pointer) error {
	return (*payexpense.Expense)(p).BeforeCreate(ctx)
}

func init() {
	expensesTable.Relations[0].Target = workerdb.WorkersSchema()
	expensesTable.Relations[1].Target = paycodedb.PayCodesSchema()
	expensesTable.Relations[2].Target = tenantdb.UsersSchema()
}

